begin;
select plan(17);
select has_table('public','release_information_requests','release intake and approval workflow exists');
select has_table('public','data_subject_deadline_policies','patient access deadlines are configured, not hardcoded');
select has_column('public','disclosure_register','release_request_id','released requests link to the existing disclosure register');
select has_column('public','disclosure_register','redaction_notes','disclosure register retains redaction notes');
select has_column('public','release_information_requests','requester_relationship','release intake retains requester relationship');
select has_column('public','release_information_requests','requested_scope','release intake retains requested scope');
select has_column('public','release_information_requests','identity_verified_at','identity verification is timestamped');
select has_column('public','release_information_requests','authorization_verified_at','authority verification is timestamped');
select has_column('public','release_information_requests','second_reviewed_by','sensitive release has second reviewer');
select has_column('public','release_information_requests','released_at','release time is recorded');
select has_function('public','intake_release_information_request',array['uuid','text','text','text','text','text[]','boolean'],'records staff can intake release requests');
select has_function('public','verify_release_information_request',array['uuid','text','text','text'],'identity and authority verification is an explicit step');
select has_function('public','approve_release_information_request',array['uuid','text','boolean'],'release approval supports a second reviewer');
select has_function('public','release_information_request',array['uuid','text[]','text'],'release records actual disclosures');
select has_function('public','configure_data_subject_deadline',array['uuid','text','integer','text'],'deadline basis is configurable by authorized staff');
select has_function('public','verify_data_subject_request',array['uuid','text','text'],'patient access requests have identity and authority verification');
select ok((select is_nullable='YES' from information_schema.columns where table_schema='public' and table_name='data_subject_requests' and column_name='due_at'),'no statutory deadline is imposed until configured');
select * from finish();
rollback;
